@* Confirmation dialog for revoking a session *@

@if (IsVisible)
{
    <div class="modal-backdrop-custom" @onclick="Cancel">
        <div class="modal-dialog-custom" @onclick:stopPropagation="true">
            <div class="modal-content">
                <div class="modal-header">
                    <h6 class="modal-title">Revoke Session</h6>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@DeviceName</strong>?</p>
                    <p class="text-muted small">This will sign out the device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary btn-sm" @onclick="Cancel">Cancel</button>
                    <button class="btn btn-danger btn-sm" @onclick="Confirm">Revoke</button>
