    <h4 class="mb-4">Security Settings</h4>

    @if (IsLoading)
    {
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status"></div>
        </div>
    }
    else if (Security is not null)
    {
        <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

        <div class="card mt-4">
            <div class="card-body">
                <h6 class="card-title">Two-Factor Authentication</h6>
                <div class="d-flex align-items-center gap-3">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="twoFactor"
                               checked="@TwoFactorEnabled" @onchange="e => TwoFactorEnabled = (bool)e.Value!" />
                        <label class="form-check-label" for="twoFactor">Enable 2FA</label>
                    </div>
                    <span class="badge @(TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                @if (Security.LastPasswordChange.HasValue)
                {
                    <p class="text-muted small mt-2 mb-0">
                        Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                    </p>
                }
            </div>
        </div>

        <div class="card mt-4">
            <div class="card-body">
                <h6 class="card-title">Active Sessions</h6>
                <div class="table-responsive">
                    <table class="table table-sm align-middle mb-0">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in Security.Sessions)
                            {
                                var isCurrent = session == Security.Sessions.FirstOrDefault();
                                <tr>
                                    <td>
                                        @session.Device
                                        @if (isCurrent)
                                        {
                                            <span class="badge bg-info ms-1">Current</span>
                                        }
                                    </td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (!isCurrent)
                                        {
                                            <button class="btn btn-outline-danger btn-sm"
                                                    @onclick="() => ShowRevokeDialog(session)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            </div>
        </div>

        <RevokeSessionDialog IsVisible="@ShowConfirmDialog"
                             DeviceName="@(SessionToRevoke?.Device ?? "")"
                             OnConfirm="ConfirmRevoke"
                             OnCancel="CancelRevoke" />
    }
</div>

@code {
    private SecuritySettings? Security;
    private bool TwoFactorEnabled;
    private bool IsLoading = true;
    private ActiveSession? SessionToRevoke;
    private bool ShowConfirmDialog;

    protected override async Task OnInitializedAsync()
    {
        await LoadSecurity();
    }

    private async Task LoadSecurity()
    {
        IsLoading = true;
        Security = await SettingsService.GetSecuritySettingsAsync();
        TwoFactorEnabled = Security.TwoFactorEnabled;
        IsLoading = false;
    }

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        Security = await SettingsService.GetSecuritySettingsAsync();
    }

    private void ShowRevokeDialog(ActiveSession session)
    {
        SessionToRevoke = session;
        ShowConfirmDialog = true;
    }

    private async Task ConfirmRevoke()
    {
        if (SessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(SessionToRevoke.Id);
            Security = await SettingsService.GetSecuritySettingsAsync();
        }
        ShowConfirmDialog = false;
        SessionToRevoke = null;
    }

    private void CancelRevoke()
    {
        ShowConfirmDialog = false;
        SessionToRevoke = null;
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

.security-section {
    padding: 0.5rem 0;
}

@using sv_88cc697a4869401cb6c5a9ef9596384c.Models
@using sv_88cc697a4869401cb6c5a9ef9596384c.Services
@inject ISettingsService SettingsService

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    @if (IsLoading)
    {
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status"></div>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-md-7">
                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title">Theme</h6>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme" id="theme-@theme"
                                       value="@theme" checked="@(SelectedTheme == theme)"
                                       @onchange="() => SelectedTheme = theme" />
                                <label class="form-check-label" for="theme-@theme">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title">Font Size</h6>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize" id="fs-@size"
                                       value="@size" checked="@(SelectedFontSize == size)"
                                       @onchange="() => SelectedFontSize = size" />
                                <label class="form-check-label" for="fs-@size">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title">Language</h6>
                        <select class="form-select" @bind="SelectedLanguage">
                            @foreach (var lang in Languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title">Layout</h6>
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode"
                                   checked="@CompactMode" @onchange="e => CompactMode = (bool)e.Value!" />
                            <label class="form-check-label" for="compactMode">Compact Mode</label>
                        </div>
                    </div>
                </div>
            </div>

            <div class="col-md-5">
                <div class="card">
                    <div class="card-header">
                        <h6 class="mb-0">Live Preview</h6>
                    </div>
                    <div class="card-body preview-area @GetPreviewClasses()">
                        <h6 style="@GetPreviewFontStyle()">Sample Heading</h6>
                        <p style="@GetPreviewFontStyle()">
                            This is how your content will look with the selected settings.
                            The quick brown fox jumps over the lazy dog.
                        </p>
                        <div class="d-flex gap-2 mt-2">
                            <button class="btn btn-primary btn-sm">Primary</button>
                            <button class="btn btn-outline-secondary btn-sm">Secondary</button>
                        </div>
                        <div class="mt-2 small text-muted">
                            Theme: @SelectedTheme · Font: @SelectedFontSize · Compact: @(CompactMode ? "On" : "Off")
                        </div>
                    </div>
                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(StatusMessage))
        {
            <div class="alert alert-success py-2 mt-2">@StatusMessage</div>
        }

        <button class="btn btn-primary mt-3" @onclick="SaveAppearance" disabled="@IsSaving">
            @(IsSaving ? "Saving…" : "Save")
        </button>
    }
</div>

@code {
    private string SelectedTheme = "Light";
    private string SelectedFontSize = "Medium";
    private string SelectedLanguage = "English";
    private bool CompactMode;
    private bool IsLoading = true;
    private bool IsSaving;
    private string? StatusMessage;

    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        IsLoading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        SelectedTheme = settings.Theme;
        SelectedFontSize = settings.FontSize;
        SelectedLanguage = settings.Language;
        CompactMode = settings.CompactMode;
        IsLoading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (SelectedTheme == "Dark") classes.Add("preview-dark");
        if (CompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private string GetPreviewFontStyle() => SelectedFontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    private async Task SaveAppearance()
    {
        IsSaving = true;
        StatusMessage = null;
        var settings = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        StatusMessage = "Appearance settings saved!";
        IsSaving = false;
    }
}

.appearance-section {
    padding: 0.5rem 0;
}

.preview-area {
    transition: background-color 0.3s, color 0.3s, padding 0.3s;
    min-height: 180px;
    border-radius: 0 0 0.375rem 0.375rem;
}

