    background-color: #1e1e2e;
    color: #cdd6f4;
}

.preview-dark .btn-primary {
    background-color: #89b4fa;
    border-color: #89b4fa;
    color: #1e1e2e;
}

.preview-dark .btn-outline-secondary {
    color: #a6adc8;
    border-color: #585b70;
}

.preview-dark .text-muted {
    color: #6c7086 !important;
}

.preview-compact {
    padding: 0.5rem !important;
    line-height: 1.3;
}

