                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(StatusMessage))
        {
            <div class="alert @(IsError ? "alert-danger" : "alert-success") py-2 mt-2">@StatusMessage</div>
        }

        <div class="mt-3 d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveChanges" disabled="@IsSaving">
                @(IsSaving ? "Saving…" : "Save Changes")
            </button>
            <button class="btn btn-outline-secondary" @onclick="DiscardChanges">
                Discard Changes
            </button>
        </div>
    }
</div>

@code {
    private UserProfile? Profile;
    private string EditName = "";
    private string EditEmail = "";
    private string EditBio = "";
    private bool IsLoading = true;
    private bool IsSaving;
    private string? StatusMessage;
    private bool IsError;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
    }

    private async Task LoadProfile()
    {
        IsLoading = true;
        Profile = await SettingsService.GetProfileAsync();
        ResetForm();
        IsLoading = false;
    }

    private void ResetForm()
    {
        if (Profile is null) return;
        EditName = Profile.DisplayName;
        EditEmail = Profile.Email;
        EditBio = Profile.Bio;
        StatusMessage = null;
    }

    private async Task SaveChanges()
    {
        if (Profile is null) return;
        IsSaving = true;
        StatusMessage = null;
        try
        {
            var updated = Profile with
            {
                DisplayName = EditName,
                Email = EditEmail,
                Bio = EditBio
            };
            await SettingsService.SaveProfileAsync(updated);
            Profile = updated;
            StatusMessage = "Profile saved successfully!";
            IsError = false;
        }
        catch (Exception ex)
        {
            StatusMessage = $"Error saving profile: {ex.Message}";
            IsError = true;
        }
        finally
        {
            IsSaving = false;
        }
    }

    private void DiscardChanges()
    {
        ResetForm();
    }
}
