                                <input class="form-check-input" type="radio" name="fontSize" id="fs-@size"
                                       value="@size" checked="@(SelectedFontSize == size)"
                                       @onchange="() => SelectedFontSize = size" />
                                <label class="form-check-label" for="fs-@size">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title">Language</h6>
                        <select class="form-select" @bind="SelectedLanguage">
                            @foreach (var lang in Languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title">Layout</h6>
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode"
                                   checked="@CompactMode" @onchange="e => CompactMode = (bool)e.Value!" />
                            <label class="form-check-label" for="compactMode">Compact Mode</label>
                        </div>
                    </div>
                </div>
            </div>

            <div class="col-md-5">
                <div class="card">
                    <div class="card-header">
                        <h6 class="mb-0">Live Preview</h6>
                    </div>
                    <div class="card-body preview-area @GetPreviewClasses()">
                        <h6 style="@GetPreviewFontStyle()">Sample Heading</h6>
                        <p style="@GetPreviewFontStyle()">
                            This is how your content will look with the selected settings.
                            The quick brown fox jumps over the lazy dog.
                        </p>
                        <div class="d-flex gap-2 mt-2">
                            <button class="btn btn-primary btn-sm">Primary</button>
                            <button class="btn btn-outline-secondary btn-sm">Secondary</button>
                        </div>
                        <div class="mt-2 small text-muted">
                            Theme: @SelectedTheme · Font: @SelectedFontSize · Compact: @(CompactMode ? "On" : "Off")
                        </div>
                    </div>
                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(StatusMessage))
        {
            <div class="alert alert-success py-2 mt-2">@StatusMessage</div>
        }

        <button class="btn btn-primary mt-3" @onclick="SaveAppearance" disabled="@IsSaving">
            @(IsSaving ? "Saving…" : "Save")
        </button>
    }
</div>

@code {
    private string SelectedTheme = "Light";
    private string SelectedFontSize = "Medium";
    private string SelectedLanguage = "English";
    private bool CompactMode;
    private bool IsLoading = true;
    private bool IsSaving;
    private string? StatusMessage;

    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        IsLoading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        SelectedTheme = settings.Theme;
        SelectedFontSize = settings.FontSize;
        SelectedLanguage = settings.Language;
        CompactMode = settings.CompactMode;
        IsLoading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (SelectedTheme == "Dark") classes.Add("preview-dark");
        if (CompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private string GetPreviewFontStyle() => SelectedFontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    private async Task SaveAppearance()
    {
        IsSaving = true;
        StatusMessage = null;
        var settings = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        StatusMessage = "Appearance settings saved!";
        IsSaving = false;
    }
}
