@inject ISettingsService SettingsService

<div class="profile-section">
    <h4 class="mb-4">Profile Settings</h4>

    @if (IsLoading)
    {
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status"></div>
        </div>
    }
    else if (Profile is not null)
    {
        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label fw-semibold">Display Name</label>
                    <input type="text" class="form-control" @bind="EditName" />
                </div>
                <div class="mb-3">
                    <label class="form-label fw-semibold">Email</label>
                    <input type="email" class="form-control" @bind="EditEmail" />
                </div>
                <div class="mb-3">
                    <label class="form-label fw-semibold">Bio</label>
                    <textarea class="form-control" rows="4" @bind="EditBio"></textarea>
                </div>
            </div>
            <div class="col-md-4">
                <div class="avatar-preview text-center">
                    <img src="@Profile.AvatarUrl" alt="Avatar" class="rounded-circle mb-2" width="120" height="120" />
                    <div class="small text-muted text-break">@Profile.AvatarUrl</div>
                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(StatusMessage))
        {
            <div class="alert @(IsError ? "alert-danger" : "alert-success") py-2 mt-2">@StatusMessage</div>
        }

        <div class="mt-3 d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveChanges" disabled="@IsSaving">
                @(IsSaving ? "Saving…" : "Save Changes")
            </button>
            <button class="btn btn-outline-secondary" @onclick="DiscardChanges">
                Discard Changes
            </button>
        </div>
    }
</div>

@code {
    private UserProfile? Profile;
    private string EditName = "";
    private string EditEmail = "";
    private string EditBio = "";
    private bool IsLoading = true;
    private bool IsSaving;
    private string? StatusMessage;
    private bool IsError;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
    }

    private async Task LoadProfile()
    {
        IsLoading = true;
        Profile = await SettingsService.GetProfileAsync();
        ResetForm();
        IsLoading = false;
    }

    private void ResetForm()
    {
        if (Profile is null) return;
        EditName = Profile.DisplayName;
        EditEmail = Profile.Email;
        EditBio = Profile.Bio;
        StatusMessage = null;
    }

    private async Task SaveChanges()
    {
        if (Profile is null) return;
        IsSaving = true;
        StatusMessage = null;
        try
        {
            var updated = Profile with
            {
                DisplayName = EditName,
                Email = EditEmail,
                Bio = EditBio
            };
            await SettingsService.SaveProfileAsync(updated);
            Profile = updated;
            StatusMessage = "Profile saved successfully!";
            IsError = false;
        }
        catch (Exception ex)
        {
            StatusMessage = $"Error saving profile: {ex.Message}";
            IsError = true;
        }
        finally
        {
            IsSaving = false;
        }
    }

    private void DiscardChanges()
    {
        ResetForm();
    }
}

